'use client';
import type { CaptureSetupView } from '@salesmora/contracts';
import { CaptureFormFieldEditor } from '../../lead-capture/capture-form-field-editor/capture-form-field-editor';
import { CaptureLeadWorkflow } from '../../lead-capture/capture-lead-workflow/capture-lead-workflow';
import { GmailFieldMapping } from '../../lead-capture/gmail-field-mapping/gmail-field-mapping';
/** Same canonical editors as manual setup, frozen to the server-reviewed configuration. */
export function CaptureSetupProjection({ view }: { view: CaptureSetupView }) {
  const labels: Record<string, string> = { businessName: 'Business name', title: 'Form title', intro: 'Introduction', submitLabel: 'Submit button', thankYou: 'Thank-you message', unavailableMessage: 'Unavailable message', businessEmail: 'Business email', businessPhone: 'Business phone', showBusinessEmail: 'Show business email', showBusinessPhone: 'Show business phone', privacy: 'Privacy link', consent: 'Consent' };
  const { configuration: config, sample, findings, name, before } = view.review, workflow = config.workflow;
  return <div className="grid min-w-0 gap-4"><p className="m-0 text-sm font-semibold wrap-anywhere">{name} · {config.type === 'website' ? 'Website form' : 'Gmail capture'}</p>
    <p className="m-0 text-sm text-muted">{['suggest_website_fields', 'suggest_workflow', 'extract_sample', 'refine_mapping'].includes(view.ticket.operation) ? 'Confirmation applies suggestions to this unsaved setup. Save separately to keep the changes.' : view.ticket.operation === 'approve_sample' ? 'Confirmation retains this pasted sample and approved mapping for setup. Gmail connection and publication still require separate checks.' : 'Confirmation saves a source draft. Publication requires a separate review.'}</p>
    {before && <details><summary className="min-h-11 cursor-pointer text-sm">Previously saved configuration</summary><p className="text-sm wrap-anywhere">Fields: {before.fields?.map(field => field.label).join(', ') || 'None'}. Stage: {before.workflow?.stage ?? 'Not set'}. Tags: {before.workflow?.tags.join(', ') || 'None'}.</p></details>}
    <CaptureFormFieldEditor heading={config.type === 'gmail' ? 'Fields extracted from email' : undefined} description={config.type === 'gmail' ? 'Review field labels, types, choices and required settings.' : undefined} value={{ fields: config.fields ?? [], contactRequired: config.contactRequired ?? true }} canRead canEdit={false} readOnlyMessage="These are the exact reviewed fields." onChange={() => {}} />
    {workflow && <CaptureLeadWorkflow value={{ assignment: workflow.assignment.kind, teammateId: workflow.assignment.kind === 'teammate' ? workflow.assignment.teammateId : '', stage: workflow.stage, tagsText: workflow.tags.join(', '), notifyAssigned: workflow.notifyAssigned }} teammates={workflow.assignment.kind === 'teammate' ? [{ id: workflow.assignment.teammateId, name: workflow.assignment.teammateId }] : []} source={config.type} canRead canEdit={false} readOnlyMessage="Notifications apply only when a future active source admits a request." onChange={() => {}} />}
    {config.type === 'website' && <><p className="text-sm whitespace-pre-wrap wrap-anywhere">Brief: {config.brief || 'Not set'}</p><dl className="m-0 grid gap-2">{Object.entries(config.content ?? {}).map(([key, value]) => <div key={key} className="min-w-0"><dt className="text-xs text-muted">{labels[key] ?? key}</dt><dd className="m-0 text-sm whitespace-pre-wrap wrap-anywhere">{value && typeof value === 'object' ? 'href' in value ? `${value.label}: ${value.href}` : `${value.label} (${value.required ? 'Required' : 'Optional'})` : value === null ? 'Not set' : typeof value === 'boolean' ? value ? 'Yes' : 'No' : String(value)}</dd></div>)}</dl></>}
    {config.type === 'gmail' && <><p className="text-sm wrap-anywhere">Match {config.rules?.mode ?? 'all'} phrases in {config.rules?.location ?? 'both'}: {config.rules?.phrases.join(', ') || 'Not set'}</p><p className="text-sm text-muted">A pasted sample does not connect a mailbox or send emails.</p>{sample && <GmailFieldMapping readOnlyMessage="These are the exact findings prepared for confirmation. Apply them to the setup to make corrections." value={{ sampleId: sample.id, sampleVersion: sample.version, findings }} sample={sample} targets={(config.fields ?? []).map(field => ({ ...field }))} rules={{ location: config.rules?.location ?? 'both', mode: config.rules?.mode ?? 'all', phrases: (config.rules?.phrases ?? []).map((text, index) => ({ id: `phrase-${index}`, text })) }} messages={[]} canRead canEdit={false} onChange={() => {}} onBack={() => {}} onSend={async () => {}} onApprove={async () => {}} />}</>}
  </div>;
}
